if mibBuilder.loadTexts: cefLMPrefixTable.setDescription('A table of Longest Match Prefix Query requests.\n\n          Generator application should utilize the\n          cefLMPrefixSpinLock to try to avoid collisions.\n          See DESCRIPTION clause of cefLMPrefixSpinLock.')
cefLMPrefixEntry = MibTableRow((1, 3, 6, 1, 4, 1, 9, 9, 492, 1, 1, 4, 1), ).setMaxAccess("notaccessible").setIndexNames((0, "ENTITY-MIB", "entPhysicalIndex"), (0, "CISCO-CEF-MIB", "cefLMPrefixDestAddrType"), (0, "CISCO-CEF-MIB", "cefLMPrefixDestAddr"))
